# Surah Al-Hashr (chapter 59) — part 1: ayat 1-12 (IDs 5127-5138)
SURAH = 59

ENTRIES = {
5127: (
"بسم اللہ الرّحْمٰن الرّحِیْم — اللہ کی تسبیح کی اس نے جو آسمانوں میں ہے اور جو زمین میں ہے — اور وہ غالب حکمت والا ہے",
"""۱۔ تسبیح کا آغاز — سبّح للہ ما في السماوات و ما في الأرض؛ و هو العزیز الحکیم۔
۲۔ ’’سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ‘‘ — اللہ کی تسبیح کی اس نے جو آسمانوں میں ہے اور جو زمین میں ہے — اور وہ غالب حکمت والا ہے — یعنی اللہ کی تسبیح کی اس نے جو آسمانوں میں ہے اور جو زمین میں ہے اور وہ غالب حکمت والا ہے۔
۳۔ عملی سبق: ہر مخلوق اللہ کی تسبیح کرتی ہے؛ اللہ سے ڈرو۔"""
),
5128: (
"وہی ہے جس نے اہل کتاب کے کافروں کو ان کے گھروں سے پہلی بار جلا وطن کیا — تم نے نہیں گمان کیا تھا کہ وہ نکلیں گے — اور وہ گمان کرتے تھے کہ ان کے قلعے انہیں اللہ سے بچا لیں گے — پس اللہ ان کے پاس وہاں سے آیا جہاں سے ان کا گمان نہ تھا — اور ان کے دلوں میں رعب ڈال دیا — وہ اپنے گھروں کو اپنے ہاتھوں اور مومنوں کے ہاتھوں خراب کرتے ہیں — پس عبرت لو اے بصیرت والو",
"""۱۔ قبیلہ بنو نضیر کا جلا وطن ہونا — هو الذي أخرج الذین کفروا من أهل الکتاب من دیارهم لأول الحشر؛ ما ظننتم أن یخرجوا؛ و ظنوا أنهم مانعتهم حصونهم من الله فأتاهم الله من حیث لم یحتسبوا؛ و قذف في قلوبهم الرعب یخربون بیوتهم بأیدیهم و أيدي المؤمنین؛ فاعتبروا یا أولي الأبصار۔
۲۔ ’’هُوَ الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ مِن دِيَارِهِمْ لِأَوَّلِ الْحَشْرِ مَا ظَنَنتُمْ أَن يَخْرُجُوا وَظَنُّوا أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ اللَّهِ فَأَتَاهُمُ اللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا وَقَذَفَ فِي قُلُوبِهِمُ الرُّعْبَ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِي الْمُؤْمِنِينَ فَاعْتَبِرُوا يَا أُولِي الْأَبْصَارِ‘‘ — وہی ہے جس نے اہل کتاب کے کافروں کو ان کے گھروں سے پہلی بار جلا وطن کیا — تم نے نہیں گمان کیا تھا کہ وہ نکلیں گے — اور وہ گمان کرتے تھے کہ ان کے قلعے انہیں اللہ سے بچا لیں گے — پس اللہ ان کے پاس وہاں سے آیا جہاں سے ان کا گمان نہ تھا — اور ان کے دلوں میں رعب ڈال دیا — وہ اپنے گھروں کو اپنے ہاتھوں اور مومنوں کے ہاتھوں خراب کرتے ہیں — پس عبرت لو اے بصیرت والو — یعنی وہی ہے جس نے اہل کتاب کے کافروں کو ان کے گھروں سے پہلی بار جلا وطن کیا تم نے نہیں گمان کیا تھا کہ وہ نکلیں گے اور وہ گمان کرتے تھے کہ ان کے قلعے انہیں اللہ سے بچا لیں گے پس اللہ ان کے پاس وہاں سے آیا جہاں سے ان کا گمان نہ تھا اور ان کے دلوں میں رعب ڈال دیا وہ اپنے گھروں کو اپنے ہاتھوں اور مومنوں کے ہاتھوں خراب کرتے ہیں پس عبرت لو اے بصیرت والو۔
۳۔ عملی سبق: عبرت حاصل کرو؛ اللہ سے ڈرو۔"""
),
5129: (
"اور اگر اللہ نے ان پر جلا وطنی لکھی نہ ہوتی تو وہ انہیں دنیا میں عذاب دیتا — اور آخرت میں ان کے لیے آگ کا عذاب ہے",
"""۱۔ اللہ کا فیصلہ — و لولا أن کتب الله علیهم الجلاء لعذبهم في الدنیا؛ و لهم في الآخرة عذاب النار۔
۲۔ ’’وَلَوْلَا أَن كَتَبَ اللَّهُ عَلَيْهِمُ الْجَلَاءَ لَعَذَّبَهُمْ فِي الدُّنْيَا وَلَهُمْ فِي الْآخِرَۃِ عَذَابُ النَّارِ‘‘ — اور اگر اللہ نے ان پر جلا وطنی لکھی نہ ہوتی تو وہ انہیں دنیا میں عذاب دیتا — اور آخرت میں ان کے لیے آگ کا عذاب ہے — یعنی اور اگر اللہ نے ان پر جلا وطنی لکھی نہ ہوتی تو وہ انہیں دنیا میں عذاب دیتا اور آخرت میں ان کے لیے آگ کا عذاب ہے۔
۳۔ عملی سبق: اللہ کے فیصلے پر صبر کرو؛ اللہ سے ڈرو۔"""
),
5130: (
"یہ اس لیے کہ انہوں نے اللہ اور اس کے رسول کی مخالفت کی — اور جو اللہ کی مخالفت کرے تو بے شک اللہ سخت سزا والا ہے",
"""۱۔ مخالفت کا انجام — ذلک بأنهم شاقّوا الله و رسوله؛ و من یُشاقّ الله فإن الله شدید العقاب۔
۲۔ ’’ذَٰلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِّ اللَّهَ فَإِنَّ اللَّهَ شَدِيدُ الْعِقَابِ‘‘ — یہ اس لیے کہ انہوں نے اللہ اور اس کے رسول کی مخالفت کی — اور جو اللہ کی مخالفت کرے تو بے شک اللہ سخت سزا والا ہے — یعنی یہ اس لیے کہ انہوں نے اللہ اور اس کے رسول کی مخالفت کی اور جو اللہ کی مخالفت کرے تو بے شک اللہ سخت سزا والا ہے۔
۳۔ عملی سبق: اللہ اور رسول کی مخالفت نہ کرو؛ اللہ سے ڈرو۔"""
),
5131: (
"جو کھجور کے درخت تم نے کاٹے یا جنہیں اپنی جڑوں پر کھڑا رہنے دیا — وہ اللہ کے حکم سے — اور تاکہ وہ فاسقوں کو ذلیل کرے",
"""۱۔ نخلہ کا کاٹنا — ما قطعتم من لینۃ أو ترکتموا قائمة علی أصولها فبإذن الله و لیخزی الفاسقین۔
۲۔ ’’مَا قَطَعْتُم مِّن لِّينَۃٍ أَوْ تَرَكْتُمُوهَا قَائِمَۃً عَلَىٰ أُصُولِهَا فَبِإِذْنِ اللَّهِ وَلِيُخْزِيَ الْفَاسِقِينَ‘‘ — جو کھجور کے درخت تم نے کاٹے یا جنہیں اپنی جڑوں پر کھڑا رہنے دیا — وہ اللہ کے حکم سے — اور تاکہ وہ فاسقوں کو ذلیل کرے — یعنی جو کھجور کے درخت تم نے کاٹے یا جنہیں اپنی جڑوں پر کھڑا رہنے دیا وہ اللہ کے حکم سے اور تاکہ وہ فاسقوں کو ذلیل کرے۔
۳۔ عملی سبق: اللہ کے احکام پر یقین رکھو؛ اللہ سے ڈرو۔"""
),
5132: (
"اور جو اللہ نے ان کی طرف سے اپنے رسول کو فئے دیا پس تم نے اس پر نہ گھوڑے دوڑائے نہ اونٹ — لیکن اللہ اپنے رسولوں کو جس پر چاہے غالب کرتا ہے — اور اللہ ہر چیز پر قادر ہے",
"""۱۔ فئے — و ما أفاء الله علی رسوله منهم فما أوجفتم علیه من خیل و لا رکاب؛ و لکنّ الله یسلّط رسله علی من یشاء؛ و الله علی کل شيء قدیر۔
۲۔ ’’وَمَا أَفَاءَ اللَّهُ عَلَىٰ رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَٰكِنَّ اللَّهَ يُسَلِّطُ رُسُلَهُ عَلَىٰ مَن يَشَاءُ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ‘‘ — اور جو اللہ نے ان کی طرف سے اپنے رسول کو فئے دیا پس تم نے اس پر نہ گھوڑے دوڑائے نہ اونٹ — لیکن اللہ اپنے رسولوں کو جس پر چاہے غالب کرتا ہے — اور اللہ ہر چیز پر قادر ہے — یعنی اور جو اللہ نے ان کی طرف سے اپنے رسول کو فئے دیا پس تم نے اس پر نہ گھوڑے دوڑائے نہ اونٹ لیکن اللہ اپنے رسولوں کو جس پر چاہے غالب کرتا ہے اور اللہ ہر چیز پر قادر ہے۔
۳۔ عملی سبق: اللہ کے فیصلے پر شکر کرو؛ اللہ سے ڈرو۔"""
),
5133: (
"جو اللہ نے اپنے رسول کو فئے دیا بستیوں سے ان میں اللہ کا حق ہے اور رسول کا اور رشتہ داروں کا اور یتیموں کا اور مساکین کا اور مسافر کا — تاکہ یہ مال تمہارے امیر لوگوں کے درمیان دولت نہ بنے — اور رسول تمہیں جو دے وہ لو اور جس سے روکے وہ رک جاؤ — اور اللہ سے ڈرو — بے شک اللہ سخت سزا والا ہے",
"""۱۔ فئے کی تقسیم — ما أفاء الله علی رسوله من أهل القری فلله و للرسول و لذي القربی و الیتامی و المساکین و ابن السبیل؛ کی لا یکون دولۃ بین الأغنیاء منکم؛ و ما آتاکم الرسول فخذوه و ما نهاکم عنه فانتهوا؛ و اتقوا الله؛ إن الله شدید العقاب۔
۲۔ ’’مَّا أَفَاءَ اللَّهُ عَلَىٰ رَسُولِهِ مِنْ أَهْلِ الْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ كَيْ لَا يَكُونَ دُولَۃً بَيْنَ الْأَغْنِيَاءِ مِنكُمْ وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانتَهُوا وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ‘‘ — جو اللہ نے اپنے رسول کو فئے دیا بستیوں سے ان میں اللہ کا حق ہے اور رسول کا اور رشتہ داروں کا اور یتیموں کا اور مساکین کا اور مسافر کا — تاکہ یہ مال تمہارے امیر لوگوں کے درمیان دولت نہ بنے — اور رسول تمہیں جو دے وہ لو اور جس سے روکے وہ رک جاؤ — اور اللہ سے ڈرو — بے شک اللہ سخت سزا والا ہے — یعنی جو اللہ نے اپنے رسول کو فئے دیا بستیوں سے ان میں اللہ کا حق ہے اور رسول کا اور رشتہ داروں کا اور یتیموں کا اور مساکین کا اور مسافر کا تاکہ یہ مال تمہارے امیر لوگوں کے درمیان دولت نہ بنے اور رسول تمہیں جو دے وہ لو اور جس سے روکے وہ رک جاؤ اور اللہ سے ڈرو بے شک اللہ سخت سزا والا ہے۔
۳۔ عملی سبق: رسول کی اطاعت کرو؛ اللہ سے ڈرو۔"""
),
5134: (
"ان مہاجر مساکین کے لیے جو اپنے گھروں اور مالوں سے نکالے گئے اللہ کا فضل اور اس کی خوشنودی چاہتے ہیں اور اللہ اور اس کے رسول کی مدد کرتے ہیں — یہی سچے ہیں",
"""۱۔ مہاجرین — للفقراء المهاجرین الذین أخرجوا من دیارهم و أموالهم یبتغون فضلًا من الله و رضوانًا و ینصرون الله و رسوله؛ أولئک هم الصادقون۔
۲۔ ’’لِّلْفُقَرَاءِ الْمُهَاجِرِينَ الَّذِينَ أُخْرِجُوا مِن دِيَارِهِمْ وَأَمْوَالِهِمْ يَبْتَغُونَ فَضْلًا مِّنَ اللَّهِ وَرِضْوَانًا وَيَنصُرُونَ اللَّهَ وَرَسُولَهُ أُولَٰئِكَ هُمُ الصَّادِقُونَ‘‘ — ان مہاجر مساکین کے لیے جو اپنے گھروں اور مالوں سے نکالے گئے اللہ کا فضل اور اس کی خوشنودی چاہتے ہیں اور اللہ اور اس کے رسول کی مدد کرتے ہیں — یہی سچے ہیں — یعنی ان مہاجر مساکین کے لیے جو اپنے گھروں اور مالوں سے نکالے گئے اللہ کا فضل اور اس کی خوشنودی چاہتے ہیں اور اللہ اور اس کے رسول کی مدد کرتے ہیں یہی سچے ہیں۔
۳۔ عملی سبق: اللہ اور رسول کی مدد کرو؛ اللہ سے ڈرو۔"""
),
5135: (
"اور جنہوں نے اس گھر کو اور ایمان کو اپنے ٹھکانہ بنایا ان سے پہلے — وہ ان سے محبت کرتے ہیں جو ان کی طرف ہجرت کر کے آئے اور ان کے دلوں میں کوئی حاجت نہیں جو انہیں دیے گئے اور وہ اپنے اوپر دوسروں کو ترجیح دیتے ہیں اگرچہ انہیں ضرورت ہو — اور جو اپنے نفس کے بخل سے بچے وہی کامیاب ہیں",
"""۱۔ انصار — و الذین تبوّءوا الدار و الإیمان من قبلهم یحبون من هاجر إلیهم و لا یجدون في صدورهم حاجۃ مما أوتوا و یؤثرون علی أنفسهم و لو کان بهم خصاصۃ؛ و من یُوق شح نفسه فأولئک هم المفلحون۔
۲۔ ’’وَالَّذِينَ تَبَوَّءُوا الدَّارَ وَالْإِيمَانَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِي صُدُورِهِمْ حَاجَۃً مِّمَّا أُوتُوا وَيُؤْثِرُونَ عَلَىٰ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَۃٌ وَمَن يُوقَ شُحَّ نَفْسِهِ فَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ‘‘ — اور جنہوں نے اس گھر کو اور ایمان کو اپنے ٹھکانہ بنایا ان سے پہلے — وہ ان سے محبت کرتے ہیں جو ان کی طرف ہجرت کر کے آئے اور ان کے دلوں میں کوئی حاجت نہیں جو انہیں دیے گئے اور وہ اپنے اوپر دوسروں کو ترجیح دیتے ہیں اگرچہ انہیں ضرورت ہو — اور جو اپنے نفس کے بخل سے بچے وہی کامیاب ہیں — یعنی اور جنہوں نے اس گھر کو اور ایمان کو اپنے ٹھکانہ بنایا ان سے پہلے وہ ان سے محبت کرتے ہیں جو ان کی طرف ہجرت کر کے آئے اور ان کے دلوں میں کوئی حاجت نہیں جو انہیں دیے گئے اور وہ اپنے اوپر دوسروں کو ترجیح دیتے ہیں اگرچہ انہیں ضرورت ہو اور جو اپنے نفس کے بخل سے بچے وہی کامیاب ہیں۔
۳۔ عملی سبق: دوسروں کو ترجیح دو؛ بخل سے بچو؛ اللہ سے ڈرو۔"""
),
5136: (
"اور جو ان کے بعد آئے کہتے ہیں اے ہمارے رب ہمیں اور ہمارے بھائیوں کو بخش دے جنہوں نے ہم سے پہلے ایمان لائے اور ایمان والوں کے لیے ہمارے دلوں میں کوئی کدورت نہ رکھ — اے ہمارے رب بے شک تو نہایت مہربان رحم والا ہے",
"""۱۔ بعد والے مؤمن — و الذین جاءوا من بعدهم یقولون ربنا اغفر لنا و لإخواننا الذین سبقونا بالإیمان و لا تجعل في قلوبنا غلًا للذین آمنوا؛ ربنا إنک رءوف رحیم۔
۲۔ ’’وَالَّذِينَ جَاءُوا مِن بَعْدِهِمْ يَقُولُونَ رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ‘‘ — اور جو ان کے بعد آئے کہتے ہیں اے ہمارے رب ہمیں اور ہمارے بھائیوں کو بخش دے جنہوں نے ہم سے پہلے ایمان لائے اور ایمان والوں کے لیے ہمارے دلوں میں کوئی کدورت نہ رکھ — اے ہمارے رب بے شک تو نہایت مہربان رحم والا ہے — یعنی اور جو ان کے بعد آئے کہتے ہیں اے ہمارے رب ہمیں اور ہمارے بھائیوں کو بخش دے جنہوں نے ہم سے پہلے ایمان لائے اور ایمان والوں کے لیے ہمارے دلوں میں کوئی کدورت نہ رکھ اے ہمارے رب بے شک تو نہایت مہربان رحم والا ہے۔
۳۔ عملی سبق: صحابہ کرام اور مؤمنین کے لیے دعا کرو؛ اللہ سے ڈرو۔"""
),
5137: (
"کیا تو نہیں دیکھتا انہیں جو نفاق کرتے ہیں — وہ اپنے بھائیوں سے جو کافر ہیں اہل کتاب کہتے ہیں اگر تم نکالے گئے تو ہم تمہارے ساتھ نکلیں گے اور تمہارے بارے میں ہم کبھی کسی کی بات نہیں مانیں گے — اور اگر تم سے جنگ کی گئی تو ہم تمہاری مدد کریں گے — اور اللہ گواہی دیتا ہے کہ وہ جھوٹے ہیں",
"""۱۔ منافقین کی خیانت — ألم تر إلی الذین نافقوا یقولون لإخوانهم الذین کفروا من أهل الکتاب لئن أخرجتم لنخرجنّ معکم و لا نطیع فیکم أحدًا أبدًا و إن قوتلتم لننصرنّکم؛ و الله یشهد إنهم لکاذبون۔
۲۔ ’’أَلَمْ تَرَ إِلَى الَّذِينَ نَافَقُوا يَقُولُونَ لِإِخْوَانِهِمُ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَاللَّهُ يَشْهَدُ إِنَّهُمْ لَكَاذِبُونَ‘‘ — کیا تو نہیں دیکھتا انہیں جو نفاق کرتے ہیں — وہ اپنے بھائیوں سے جو کافر ہیں اہل کتاب کہتے ہیں اگر تم نکالے گئے تو ہم تمہارے ساتھ نکلیں گے اور تمہارے بارے میں ہم کبھی کسی کی بات نہیں مانیں گے — اور اگر تم سے جنگ کی گئی تو ہم تمہاری مدد کریں گے — اور اللہ گواہی دیتا ہے کہ وہ جھوٹے ہیں — یعنی کیا تو نہیں دیکھتا انہیں جو نفاق کرتے ہیں وہ اپنے بھائیوں سے جو کافر ہیں اہل کتاب کہتے ہیں اگر تم نکالے گئے تو ہم تمہارے ساتھ نکلیں گے اور تمہارے بارے میں ہم کبھی کسی کی بات نہیں مانیں گے اور اگر تم سے جنگ کی گئی تو ہم تمہاری مدد کریں گے اور اللہ گواہی دیتا ہے کہ وہ جھوٹے ہیں۔
۳۔ عملی سبق: نفاق سے بچو؛ اللہ سے ڈرو۔"""
),
5138: (
"اگر وہ نکالے گئے تو منافقین ان کے ساتھ نہیں نکلیں گے — اور اگر ان سے جنگ کی گئی تو وہ ان کی مدد نہیں کریں گے — اور اگر ان کی مدد کریں گے تو وہ پیٹھ دکھا دیں گے — پھر وہ مدد نہیں پائیں گے",
"""۱۔ منافقین کی حقیقت — لئن أخرجوا لا یخرجون معهم؛ و لئن قوتلوا لا ینصرونهم؛ و لئن نصروهم لیولّنّ الأدبار ثم لا ینصرون۔
۲۔ ’’لَئِنْ أُخْرِجُوا لَا يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُوا لَا يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ الْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ‘‘ — اگر وہ نکالے گئے تو منافقین ان کے ساتھ نہیں نکلیں گے — اور اگر ان سے جنگ کی گئی تو وہ ان کی مدد نہیں کریں گے — اور اگر ان کی مدد کریں گے تو وہ پیٹھ دکھا دیں گے — پھر وہ مدد نہیں پائیں گے — یعنی اگر وہ نکالے گئے تو منافقین ان کے ساتھ نہیں نکلیں گے اور اگر ان سے جنگ کی گئی تو وہ ان کی مدد نہیں کریں گے اور اگر ان کی مدد کریں گے تو وہ پیٹھ دکھا دیں گے پھر وہ مدد نہیں پائیں گے۔
۳۔ عملی سبق: منافقین کی مدد پر بھروسہ نہ کرو؛ اللہ سے ڈرو۔"""
),
}
